graphql.query:
query address {
  address(address: {
      streetAddressLines: [
        "801 E William Cannon Dr Suite 401"
      ],
      administrativeArea: "TX",
      locality: "Austin",
      postalCode: "78745",
      country: "US"
    }){
    ...AddressFields
  }
}

fragment AddressFields on PreOrderAddress {
  regionId
  propertyTimeZone
  addressLatitude
  addressLongitude
  placeId
  geoCodePrecision
  addressString
  streetAddressLines
  administrativeArea
  locality
  dependentLocality
  postalCode
  sortingCode
  country
}

mutation createPreOrder($input: CaptureSvcsPreOrderInput) {
  newPreOrder(input: $input) {
    id
    preOrderStatus
    availability {
      date
      availableSlots {
        startTime
        endTime
      }
    }
  }
}

